#include <cstdio>
#include <vector>
#include <queue>
#include <cstring>
#include <cctype>
#include <algorithm>
using namespace std;
const int move_dir[4][2] = {{-1,0},{1,0},{0,-1},{0,1}};
int start, end_node, edge_count=1, size, max_time, INF, head[1000], queue_buffer[1000000], edges[1000000][3], depth[20][20], distance[20][20], point[20][20], supply[20][20];
char gridA[20][20], gridB[20][20];

void addEdge(int x, int y, int capacity) {
    edges[++edge_count][0]=y; edges[edge_count][1]=capacity; edges[edge_count][2]=head[x]; head[x]=edge_count;
    edges[++edge_count][0]=x; edges[edge_count][1]=0; edges[edge_count][2]=head[y]; head[y]=edge_count;
}

void perform_bfs(int x0, int y0, bool check) {
    int left=1, right=1, id=point[x0][y0];
    queue_buffer[left]=x0*1000 + y0;
    memset(distance, 63, sizeof(distance));
    INF=distance[0][0];
    distance[x0][y0]=0;
    while (left<=right) {
        int x=queue_buffer[left]/1000, y=queue_buffer[left]%1000; left++;
        if (check && supply[x][y]!=0 && distance[x][y]<=max_time && distance[x][y]<=depth[x][y])
            addEdge(id, supply[x][y], INF);
        if (distance[x][y]>max_time || distance[x][y]>=depth[x][y]) continue;
