            if (nx>0 && nx<=size && ny>0 && ny<=size && isdigit(gridA[nx][ny]) && distance[nx][ny]==INF) {
                distance[nx][ny]=distance[x][y]+1;
                queue_buffer[++right]=nx*1000+ny;
            }
        }
    }
}

int dist_arr[1000];

bool construct_path() {
    memset(dist_arr, 0, sizeof(dist_arr));
    int l=1, r=1; queue_buffer[l]=start; dist_arr[start]=1;
    while (l<=r) {
        int x=queue_buffer[l++]; 
        for (int i=head[x]; i; i=edges[i][2]) {
            int y=edges[i][0];
            if (dist_arr[y] || !edges[i][1]) continue;
            dist_arr[y]=dist_arr[x]+1; queue_buffer[++r]=y;
            if (y==end_node) return true;
        }
    }
    return false;
}

int flow_dfs(int x, int flow) {
    if (x==end_node) return flow;
    int remaining=flow;
