        int pushed=flow_dfs(y, min(remaining, edges[i][1]));
        remaining-=pushed; edges[i][1]-=pushed; edges[i^1][1]+=pushed;
        if (remaining==0) return flow;
    }
    if (remaining==flow) dist_arr[x]=-1;
    return flow - remaining;
