    for (int i=1; i<=size; i++)
        for (int j=1; j<=size; j++)
            if (point[i][j]) perform_bfs(i,j,true);
    int total=0;
    while (construct_path()) total+=flow_dfs(start, INF);
    printf("%d\n", total);
    return 0;
}
