import java.util.*;
import java.io.*;

public class Main {
    static final int[][] move_dir = {{-1,0},{1,0},{0,-1},{0,1}};
    static int start, end_node, edge_count=1, size, max_time, INF;
    static int[] head = new int[1000];
    static int[] queue_buffer = new int[1000000];
    static int[][] edges = new int[1000000][3];
    static int[][] depth = new int[20][20];
    static int[][] distance = new int[20][20];
    static int[][] point = new int[20][20];
    static int[][] supply = new int[20][20];
    static char[][] gridA = new char[20][20];
    static char[][] gridB = new char[20][20];

    static void addEdge(int x, int y, int capacity) {
        edges[++edge_count][0] = y;
        edges[edge_count][1] = capacity;
        edges[edge_count][2] = head[x];
        head[x] = edge_count;
        edges[++edge_count][0] = x;
        edges[edge_count][1] = 0;
        edges[edge_count][2] = head[y];
        head[y] = edge_count;
    }

    static void perform_bfs(int x0, int y0, boolean check) {
        int left=1, right=1, id=point[x0][y0];
        queue_buffer[left]=x0*1000 + y0;
        for (int[] row : distance) Arrays.fill(row, Integer.MAX_VALUE/2);
        INF=distance[0][0];
        distance[x0][y0]=0;
        while (left<=right) {
            int val=queue_buffer[left++];
            int x=val/1000, y=val%1000;
            if (check && supply[x][y]!=0 && distance[x][y]<=max_time && distance[x][y]<=depth[x][y])
                addEdge(id, supply[x][y], Integer.MAX_VALUE/2);
            if (distance[x][y]>max_time || distance[x][y]>=depth[x][y]) continue;
            if (id==3 && supply[x][y]==9) System.out.println(distance[x][y]);
            for (int i=0; i<4; i++) {
                int nx=x+move_dir[i][0], ny=y+move_dir[i][1];
                if (nx>0 && nx<=size && ny>0 && ny<=size && Character.isDigit(gridA[nx][ny]) && distance[nx][ny]==Integer.MAX_VALUE/2) {
                    distance[nx][ny]=distance[x][y]+1;
                    queue_buffer[++right]=nx*1000+ny;
                }
            }
        }
    }

    static int[] dist_arr = new int[1000];

    static boolean construct_path() {
        Arrays.fill(dist_arr, 0);
        int l=1, r=1; queue_buffer[l]=start; dist_arr[start]=1;
        while (l<=r) {
            int x=queue_buffer[l++];
            for (int i=head[x]; i!=0; i=edges[i][2]) {
                int y=edges[i][0];
                if (dist_arr[y]!=0 || edges[i][1]==0) continue;
                dist_arr[y]=dist_arr[x]+1; queue_buffer[++r]=y;
                if (y==end_node) return true;
            }
        }
        return false;
    }

    static int flow_dfs(int x, int flow) {
        if (x==end_node) return flow;
        int remaining=flow;
        for (int i=head[x]; i!=0; i=edges[i][2]) {
            int y=edges[i][0];
            if (dist_arr[y]!=dist_arr[x]+1 || edges[i][1]==0) continue;
            int pushed=flow_dfs(y, Math.min(remaining, edges[i][1]));
            remaining-=pushed;
            edges[i][1]-=pushed;
            edges[i^1][1]+=pushed;
            if (remaining==0) return flow;
        }
        if (remaining==flow) dist_arr[x]=-1;
        return flow - remaining;
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br=new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st=new StringTokenizer(br.readLine());
        size=Integer.parseInt(st.nextToken());
        max_time=Integer.parseInt(st.nextToken());
        for (int i=1; i<=size; i++) {
            String line=br.readLine();
            for (int j=1; j<=size; j++) {
                gridA[i][j]=line.charAt(j-1);
            }
        }
        for (int i=1; i<=size; i++) {
            String line=br.readLine();
            for (int j=1; j<=size; j++) {
                gridB[i][j]=line.charAt(j-1);
            }
        }
        for (int[] row : depth) Arrays.fill(row, Integer.MAX_VALUE/2);
        for (int i=1; i<=size; i++) {
            for (int j=1; j<=size; j++) {
                if (gridA[i][j]=='Z') {
                    perform_bfs(i,j,false);
                }
            }
        }
        for (int i=0; i<20; i++) {
            Arrays.fill(depth[i], Integer.MAX_VALUE/2);
        }
        for (int i=1; i<=size; i++) {
            for (int j=1; j<=size; j++) {
                depth[i][j]=distance[i][j];
            }
        }
        int t=1;
        start=0; end_node=1;
        for (int i=1; i<=size; i++) {
            for (int j=1; j<=size; j++) {
                if (gridA[i][j]>'0' && gridA[i][j]<='9') {
                    point[i][j]=++t;
                    addEdge(start, t, gridA[i][j]-'0');
                }
                if (gridB[i][j]>'0' && gridB[i][j]<='9') {
                    supply[i][j]=++t;
                    addEdge(t, end_node, gridB[i][j]-'0');
                }
            }
        }
        for (int i=1; i<=size; i++) {
            for (int j=1; j<=size; j++) {
                if (point[i][j]!=0) {
                    perform_bfs(i,j,true);
                }
            }
        }
        int total=0;
        while (construct_path()) {
            total+=flow_dfs(start, Integer.MAX_VALUE/2);
        }
        System.out.println(total);
    }
}
